styles:
/* ===== Single career / job-posting page (scoped) ===== */
.page-career .career-hero { padding-bottom: clamp(24px, 4vw, 48px); }
.page-career .career-hero__eyebrow { margin-bottom: 20px; }
.page-career .career-hero__title {
  font-family: var(--font-display);
  font-size: clamp(40px, 6.6vw, 92px);
  line-height: 1.05; color: var(--grey-700); letter-spacing: -0.01em;
  max-width: 14ch;
}
.page-career .career-meta {
  display: flex; flex-wrap: wrap; gap: 14px;
  margin-top: clamp(24px, 3vw, 38px);
}
.page-career .career-meta__item {
  display: flex; flex-direction: column; gap: 4px;
  border: 1px solid var(--line); border-radius: var(--radius);
  padding: 14px 22px; min-width: 150px;
}
.page-career .career-meta__label {
  font-size: 12px; letter-spacing: .14em; text-transform: uppercase;
  color: var(--grey-500);
}
.page-career .career-meta__value {
  font-family: var(--font-display); font-size: clamp(17px, 1.4vw, 21px);
  color: var(--grey-900); line-height: 1.15;
}
.page-career .career-banner {
  border-radius: var(--radius-lg); overflow: hidden;
  margin-top: clamp(28px, 3.6vw, 48px); aspect-ratio: 16 / 7; background: #e8e8e8;
}
.page-career .career-banner img { width: 100%; height: 100%; object-fit: cover; }

/* Readable single-column measure */
.page-career .career-body { max-width: 760px; }
.page-career .career-block { margin-bottom: clamp(36px, 4.5vw, 60px); }
.page-career .career-block:last-child { margin-bottom: 0; }
.page-career .career-block h2 {
  font-family: var(--font-display); font-size: clamp(26px, 3vw, 40px);
  color: var(--red); line-height: 1.08; margin-bottom: clamp(14px, 1.6vw, 22px);
}
.page-career .career-block h2.is-grey { color: var(--grey-700); }
.page-career .career-block p {
  color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); line-height: 1.75;
}
.page-career .career-block p + p { margin-top: 16px; }
.page-career .career-list { margin-top: 6px; display: flex; flex-direction: column; gap: 12px; }
.page-career .career-list li {
  position: relative; padding-left: 30px;
  color: var(--grey-700); font-size: clamp(16px, 1.1vw, 18px); line-height: 1.6;
}
.page-career .career-list li::before {
  content: ""; position: absolute; left: 4px; top: .62em;
  width: 8px; height: 8px; border-radius: 50%; background: var(--red);
}

.page-career .career-apply {
  margin-top: clamp(20px, 2.4vw, 30px);
  display: flex; flex-wrap: wrap; align-items: center; gap: 18px;
}
.page-career .btn-solid {
  display: inline-flex; align-items: center; gap: 14px;
  background: var(--red); color: #fff; border-radius: 999px;
  padding: 14px 16px 14px 28px; font-size: 18px;
  transition: transform .3s var(--ease), box-shadow .3s var(--ease);
}
.page-career .btn-solid .arrow {
  width: 34px; height: 34px; border-radius: 50%; background: #fff; color: var(--red);
  display: grid; place-items: center; transition: transform .3s var(--ease);
}
.page-career .btn-solid:hover { transform: translateY(-3px); box-shadow: 0 14px 30px rgba(230,0,0,.24); }
.page-career .btn-solid:hover .arrow { transform: translateX(3px); }

.page-career .career-back {
  display: inline-flex; align-items: center; gap: 10px;
  color: var(--grey-700); font-size: 16px;
  transition: color .25s var(--ease); margin-bottom: 30px;
}
.page-career .career-back:hover { color: var(--red); }
.page-career .career-allroles {
  margin-top: clamp(40px, 5vw, 64px); padding-top: 26px;
  border-top: 1px solid var(--line);
}
.page-career .career-allroles a {
  display: inline-flex; align-items: center; gap: 12px;
  font-family: var(--font-display); font-size: clamp(18px, 1.6vw, 22px);
  color: var(--grey-900); transition: color .25s var(--ease);
}
.page-career .career-allroles a:hover { color: var(--red); }
.page-career .career-allroles .arrow {
  width: 30px; height: 30px; border-radius: 50%; border: 1.5px solid var(--red); color: var(--red);
  display: grid; place-items: center; transition: background .3s var(--ease), color .3s var(--ease), transform .3s var(--ease);
}
.page-career .career-allroles a:hover .arrow { background: var(--red); color: #fff; transform: translateX(3px); }

@media (max-width: 560px) {
  .page-career .career-meta__item { flex: 1 1 100%; }
  .page-career .career-banner { aspect-ratio: 16 / 10; }
}
